From 3556b37f70dc57f73c8399297027d487342f54af Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:33:30 +0100
Subject: [PATCH] osd: Show the display configuration selector on all screens
 if asked

The selector appeared on one screen only, and always the one at 0,0 as
Qt resets a new window's screen from its geometry. Follow the OSD option
ShowOnAllScreens in plasmarc and pass the screen to layer shell as well.

BUG: 507695
---
 osd/CMakeLists.txt |  1 +
 osd/osd.cpp        |  1 +
 osd/osdmanager.cpp | 44 ++++++++++++++++++++++++++++++--------------
 3 files changed, 32 insertions(+), 14 deletions(-)

diff --git a/osd/CMakeLists.txt b/osd/CMakeLists.txt
index cb6b692d..bacc5f76 100644
--- a/osd/CMakeLists.txt
+++ b/osd/CMakeLists.txt
@@ -9,6 +9,7 @@ target_link_libraries(kscreen_osd_service PRIVATE
     kscreen_common
     Qt::DBus
     Qt::Quick
+    KF6::ConfigCore
     KF6::I18n
     KF6::WindowSystem
     KF6::Screen
diff --git a/osd/osd.cpp b/osd/osd.cpp
index 817da60f..61f08263 100644
--- a/osd/osd.cpp
+++ b/osd/osd.cpp
@@ -71,6 +71,7 @@ void Osd::showActionSelector()
     layerWindow->setLayer(LayerShellQt::Window::LayerOverlay);
     layerWindow->setAnchors({});
     layerWindow->setKeyboardInteractivity(LayerShellQt::Window::KeyboardInteractivityOnDemand);
+    layerWindow->setScreen(screen);
     m_osdActionSelector->setScreen(screen);
     m_osdActionSelector->setVisible(true);
 }
diff --git a/osd/osdmanager.cpp b/osd/osdmanager.cpp
index 94de4f7a..9d3ddf02 100644
--- a/osd/osdmanager.cpp
+++ b/osd/osdmanager.cpp
@@ -15,6 +15,9 @@
 #include <KScreen/Output>
 #include <KScreen/SetConfigOperation>

+#include <KConfig>
+#include <KConfigGroup>
+
 #include <QDBusConnection>
 #include <QDBusMessage>

@@ -95,23 +98,36 @@ void OsdManager::showActionSelector()
             return;
         }

-        KScreen::Osd *osd = nullptr;
-        if (m_osds.contains(osdOutput->name())) {
-            osd = m_osds.value(osdOutput->name());
-        } else {
-            osd = new KScreen::Osd(osdOutput, this);
-            m_osds.insert(osdOutput->name(), osd);
-            connect(osd, &Osd::osdActionSelected, this, [this, cfg = op->config()](OsdAction::Action action) {
-                auto job = OsdAction::applyAction(cfg, action);
-                if (!job) {
-                    hideOsd();
-                    return;
+        // Unless the user wants OSDs on every enabled screen
+        KScreen::OutputList osdOutputs{{osdOutput->id(), osdOutput}};
+        const KConfig plasmarc(QStringLiteral("plasmarc"));
+        if (plasmarc.group(QStringLiteral("OSD")).readEntry("ShowOnAllScreens", false)) {
+            for (const auto &output : outputs) {
+                if (output->isConnected() && output->isEnabled() && output->currentMode()) {
+                    osdOutputs.insert(output->id(), output);
                 }
-                connect(job, &KScreen::SetConfigOperation::finished, this, &OsdManager::hideOsd);
-            });
+            }
         }

-        osd->showActionSelector();
+        for (const auto &output : std::as_const(osdOutputs)) {
+            KScreen::Osd *osd = nullptr;
+            if (m_osds.contains(output->name())) {
+                osd = m_osds.value(output->name());
+            } else {
+                osd = new KScreen::Osd(output, this);
+                m_osds.insert(output->name(), osd);
+                connect(osd, &Osd::osdActionSelected, this, [this, cfg = op->config()](OsdAction::Action action) {
+                    auto job = OsdAction::applyAction(cfg, action);
+                    if (!job) {
+                        hideOsd();
+                        return;
+                    }
+                    connect(job, &KScreen::SetConfigOperation::finished, this, &OsdManager::hideOsd);
+                });
+            }
+
+            osd->showActionSelector();
+        }
         m_cleanupTimer->start();
     });
 }
-- 
2.53.0

From ac9d9238fd6ad0b67b6a6f4bc7f35b497ebebc91 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:33:29 +0100
Subject: [PATCH] shell/osd: Optionally show OSDs on all screens

OSDs only ever appeared on the active screen, so they were easy to miss
while looking at another one. With ShowOnAllScreens set in the OSD group
of plasmarc, plasmashell now places a copy of the OSD on every screen.

BUG: 507695
---
 shell/osd.cpp | 119 ++++++++++++++++++++++++++++++++++----------------
 shell/osd.h   |   6 ++-
 2 files changed, 87 insertions(+), 38 deletions(-)

diff --git a/shell/osd.cpp b/shell/osd.cpp
index 53c8b03f59..d77581dd10 100644
--- a/shell/osd.cpp
+++ b/shell/osd.cpp
@@ -16,6 +16,7 @@
 #include <QDebug>
 #include <QQmlComponent>
 #include <QQmlContext>
+#include <QQuickItem>
 #include <QScreen>
 #include <QTimer>
 #include <QWindow>
@@ -23,6 +24,8 @@
 #include <KLocalizedQmlContext>
 #include <KRuntimePlatform>
 #include <PlasmaQuick/PlasmaQuick>
+#include <PlasmaQuick/PlasmaShellWaylandIntegration>
+#include <PlasmaQuick/PlasmaWindow>
 #include <klocalizedstring.h>

 #include <algorithm> // std::ranges::sort
@@ -232,7 +235,18 @@ bool Osd::init()
         return false;
     }

-    if (m_osdObject) {
+    // Windows we placed on each screen can't be handed back to the compositor's placement, so start over
+    const bool onAllScreens = m_osdConfigGroup.readEntry("ShowOnAllScreens", false);
+    if (onAllScreens != m_onAllScreens) {
+        m_osdObjects.clear();
+        m_onAllScreens = onAllScreens;
+    }
+
+    const std::size_t count = m_onAllScreens ? std::max<std::size_t>(1, m_corona->screenPool()->screenOrder().size()) : 1;
+    if (m_osdObjects.size() > count) {
+        m_osdObjects.resize(count);
+    }
+    if (m_osdObjects.size() == count) {
         return true;
     }

@@ -243,18 +257,22 @@ bool Osd::init()
         return false;
     }

-    auto qmlContext = new QQmlContext(m_engine.get(), this);
-    auto i18ncontext = new KLocalizedQmlContext(qmlContext);
-    qmlContext->setContextObject(i18ncontext);
-    QQmlEngine::setContextForObject(i18ncontext, qmlContext);
+    while (m_osdObjects.size() < count) {
+        auto qmlContext = new QQmlContext(m_engine.get(), this);
+        auto i18ncontext = new KLocalizedQmlContext(qmlContext);
+        qmlContext->setContextObject(i18ncontext);
+        QQmlEngine::setContextForObject(i18ncontext, qmlContext);

-    m_osdObject = std::unique_ptr<QObject>(osdComponent.create(qmlContext));
+        auto osdObject = std::unique_ptr<QObject>(osdComponent.create(qmlContext));

-    if (!m_osdObject) {
-        qCWarning(PLASMASHELL) << "Failed to create OSD object" << osdComponent.errorString();
-    }
+        if (!osdObject) {
+            qCWarning(PLASMASHELL) << "Failed to create OSD object" << osdComponent.errorString();
+            return false;
+        }

-    m_timeout = m_osdObject->property("timeout").toInt();
+        m_timeout = osdObject->property("timeout").toInt();
+        m_osdObjects.push_back(std::move(osdObject));
+    }

     if (!m_osdTimer) {
         m_osdTimer = new QTimer(this);
@@ -278,12 +296,14 @@ void Osd::showProgress(const QString &icon, const int percent, const int maximum
         return;
     }

-    // Update max value first to prevent value from being clamped
-    m_osdObject->setProperty("osdMaxValue", maximumPercent);
-    m_osdObject->setProperty("osdValue", value);
-    m_osdObject->setProperty("osdAdditionalText", additionalText);
-    m_osdObject->setProperty("showingProgress", true);
-    m_osdObject->setProperty("icon", icon);
+    for (const auto &osdObject : m_osdObjects) {
+        // Update max value first to prevent value from being clamped
+        osdObject->setProperty("osdMaxValue", maximumPercent);
+        osdObject->setProperty("osdValue", value);
+        osdObject->setProperty("osdAdditionalText", additionalText);
+        osdObject->setProperty("showingProgress", true);
+        osdObject->setProperty("icon", icon);
+    }

     Q_EMIT osdProgress(icon, value, maximumPercent, additionalText);
     showOsd();
@@ -295,9 +315,11 @@ void Osd::showText(const QString &icon, const QString &text)
         return;
     }

-    m_osdObject->setProperty("showingProgress", false);
-    m_osdObject->setProperty("osdValue", text);
-    m_osdObject->setProperty("icon", icon);
+    for (const auto &osdObject : m_osdObjects) {
+        osdObject->setProperty("showingProgress", false);
+        osdObject->setProperty("osdValue", text);
+        osdObject->setProperty("icon", icon);
+    }

     Q_EMIT osdText(icon, text);
     showOsd();
@@ -307,39 +329,62 @@ void Osd::showOsd()
 {
     m_osdTimer->stop();

-    if (!m_osdObject) {
-        return;
-    }
+    const QList<QScreen *> screens = m_corona->screenPool()->screenOrder();
+    for (std::size_t i = 0; i < m_osdObjects.size(); ++i) {
+        QObject *osdObject = m_osdObjects[i].get();

-    // if our OSD understands animating the opacity, do it;
-    // otherwise just show it to not break existing lnf packages
-    if (m_osdObject->property("animateOpacity").isValid()) {
-        m_osdObject->setProperty("animateOpacity", false);
-        m_osdObject->setProperty("opacity", 1);
-        m_osdObject->setProperty("visible", true);
-        m_osdObject->setProperty("animateOpacity", true);
-        m_osdObject->setProperty("opacity", 0);
-    } else {
-        m_osdObject->setProperty("visible", true);
+        if (m_onAllScreens && i < std::size_t(screens.size())) {
+            placeOnScreen(osdObject, screens[i]);
+        }
+
+        // if our OSD understands animating the opacity, do it;
+        // otherwise just show it to not break existing lnf packages
+        if (osdObject->property("animateOpacity").isValid()) {
+            osdObject->setProperty("animateOpacity", false);
+            osdObject->setProperty("opacity", 1);
+            osdObject->setProperty("visible", true);
+            osdObject->setProperty("animateOpacity", true);
+            osdObject->setProperty("opacity", 0);
+        } else {
+            osdObject->setProperty("visible", true);
+        }
     }

     m_osdTimer->start(m_timeout);
 }

-void Osd::hide()
+void Osd::placeOnScreen(QObject *osdObject, QScreen *screen)
 {
-    if (!m_osdObject) {
+    auto window = qobject_cast<PlasmaQuick::PlasmaWindow *>(osdObject);
+    const std::optional<uint> screenId = m_corona->screenPool()->idForScreen(screen);
+    if (!window || !screenId) {
         return;
     }

+    window->setScreen(screen);
+    // The size follows the content, which only updates when polished
+    if (QQuickItem *mainItem = window->mainItem()) {
+        mainItem->ensurePolished();
+    }
+
+    // Where the compositor puts it on the active screen: centered, at two thirds of the height
+    const QRect area = m_corona->availableScreenRect(*screenId);
+    const QPoint position(area.left() + (area.width() - window->width()) / 2, area.top() + 2 * area.height() / 3 - window->height() / 2);
+    PlasmaShellWaylandIntegration::get(window)->setPosition(position);
+}
+
+void Osd::hide()
+{
     if (m_osdTimer) {
         m_osdTimer->stop();
     }

-    m_osdObject->setProperty("visible", false);
+    for (const auto &osdObject : m_osdObjects) {
+        osdObject->setProperty("visible", false);

-    // this is needed to prevent fading from "old" values when the OSD shows up
-    m_osdObject->setProperty("osdValue", 0);
+        // this is needed to prevent fading from "old" values when the OSD shows up
+        osdObject->setProperty("osdValue", 0);
+    }

     m_screenBrightnessInfo.clear();
 }
diff --git a/shell/osd.h b/shell/osd.h
index bc1071db58..ef1e7fa64b 100644
--- a/shell/osd.h
+++ b/shell/osd.h
@@ -15,6 +15,7 @@
 #include <KConfigWatcher>
 #include <KSharedConfig>

+class QScreen;
 class QTimer;
 class ShellCorona;

@@ -55,10 +56,13 @@ private:

     void showProgress(const QString &icon, const int percent, const int maximumPercent, const QString &additionalText = QString(), bool showOnMobile = true);
     void showOsd();
+    void placeOnScreen(QObject *osdObject, QScreen *screen);

     ShellCorona *const m_corona;
     std::shared_ptr<QQmlEngine> m_engine;
-    std::unique_ptr<QObject> m_osdObject = nullptr;
+    // One per screen with ShowOnAllScreens, otherwise one that the compositor places on the active screen
+    std::vector<std::unique_ptr<QObject>> m_osdObjects;
+    bool m_onAllScreens = false;
     QTimer *m_osdTimer = nullptr;
     int m_timeout = 0;

-- 
2.53.0
